import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv_transpose2d_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_height,
    int in_width,
    int kernel_size,
    int stride,
    int padding,
    int output_padding,
    int groups,
    int out_height,
    int out_width
) {
    int h_out = blockIdx.x * blockDim.x + threadIdx.x;
    int w_out = blockIdx.y * blockDim.y + threadIdx.y;
    int oc = blockIdx.z * blockDim.z + threadIdx.z;
    int b = blockIdx.w;

    if (b >= batch_size || oc >= out_channels || h_out >= out_height || w_out >= out_width) return;

    float sum = 0.0f;
    int group_size = out_channels / groups;
    int group_idx = oc / group_size;
    int in_ch_start = group_idx * (in_channels / groups);

    for (int ic = in_ch_start; ic < in_ch_start + (in_channels / groups); ++ic) {
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                int h_in = (h_out + padding - kh) / stride;
                int w_in = (w_out + padding - kw) / stride;

                if ((h_out + padding - kh) %% stride != 0) continue;
                if ((w_out + padding - kw) %% stride != 0) continue;
                if (h_in < 0 || h_in >= in_height || w_in < 0 || w_in >= in_width) continue;

                float input_val = input[b * in_channels * in_height * in_width + 
                                      ic * in_height * in_width + h_in * in_width + w_in];
                float weight_val = weight[ic * (out_channels/groups) * kernel_size * kernel_size + 
                                        (oc %% group_size) * kernel_size * kernel_size + 
                                        kh * kernel_size + kw];

                sum += input_val * weight_val;
            }
        }
    }

    if (bias) sum += bias[oc];
    output[b * out_channels * out_height * out_width + 
           oc * out_height * out_width + h_out * out_width + w_out] = sum;
}

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size,
    int stride,
    int padding,
    int output_padding,
    int groups
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_height = input.size(2);
    int in_width = input.size(3);
    int out_channels = weight.size(1) * groups;

    int out_height = (in_height - 1) * stride - 2 * padding + kernel_size + output_padding;
    int out_width = (in_width - 1) * stride - 2 * padding + kernel_size + output_padding;

    auto output = torch::zeros({batch_size, out_channels, out_height, out_width}, input.options());

    dim3 threads(8, 8, 4);
    dim3 blocks(
        (out_height + threads.x - 1) / threads.x,
        (out_width + threads.y - 1) / threads.y,
        (out_channels + threads.z - 1) / threads.z
    );

    conv_transpose2d_kernel<<<dim3(blocks.x, blocks.y, blocks.z, batch_size), threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_height,
        in_width,
        kernel_size,
        stride,
        padding,
        output_padding,
        groups,
        out_height,
        out_width
    );

    return output;
}
"""

conv_transpose2d_cpp_source = """
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size,
    int stride,
    int padding,
    int output_padding,
    int groups
);
"""

conv_transpose2d = load_inline(
    name="conv_transpose2d",
    cpp_sources=conv_transpose2d_cpp_source,
    cuda_sources=conv_transpose2d_source,
    functions=["conv_transpose2d_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self.weight = nn.Parameter(torch.Tensor(
            in_channels,
            out_channels // groups,
            kernel_size,
            kernel_size
        ))

        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose2d.conv_transpose2d_cuda(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.Tensor().cuda(),
            self.kernel_size,
            self.stride,
            self.padding,
            self.output_padding,
            self.groups
        )
